(3786686, 534117, 35352, '<td valign="top">there''s a reflective quality about this photo that goes with your title. The lighting on the gold buildings is interesting - the one of the right maybe a bit too dark. There''s a little too much walkway.</td>', 'there''s a reflective quality about this photo that goes with your title. The lighting on the gold buildings is interesting - the one of the right maybe a bit too dark. There''s a little too much walkway.', '2007-06-15 00:46:55.000000', NULL, 1),
(3786691, 531217, 35352, '<td valign="top">Interesting photo. Very personal. A shame that the fingers in the middle aren''t the ones in focus - the one of the left is.</td>', 'Interesting photo. Very personal. A shame that the fingers in the middle aren''t the ones in focus - the one of the left is.', '2007-06-15 00:47:56.000000', NULL, 1),
(3786695, 534944, 35352, '<td valign="top">Borders like this are interesting - as if this is a still from a movie. In this case, I think it really adds to the photo. Nice choice of subject, the rain water does look very pure. It seems a tad out of focus. I do like how the other leaves are blurred nicely.</td>', 'Borders like this are interesting - as if this is a still from a movie. In this case, I think it really adds to the photo. Nice choice of subject, the rain water does look very pure. It seems a tad out of focus. I do like how the other leaves are blurred nicely.', '2007-06-15 00:49:26.000000', NULL, 1),
(3786702, 532997, 35352, '<td valign="top">Nice choice of subject. The fact that there''s no little around makes for a clear and pleasing photo. The lighting is also good. The vertical lines of the buildings do seem a bit slanted.</td>', 'Nice choice of subject. The fact that there''s no little around makes for a clear and pleasing photo. The lighting is also good. The vertical lines of the buildings do seem a bit slanted.', '2007-06-15 00:50:58.000000', NULL, 1),
(3786704, 530964, 31399, '<td valign="top">AWESOME....10</td>', 'AWESOME....10', '2007-06-15 00:51:15.000000', NULL, 1),
(3786706, 533983, 31399, '<td valign="top">great job, 9</td>', 'great job, 9', '2007-06-15 00:51:31.000000', NULL, 1),
(3786709, 530678, 35352, '<td valign="top">I see your creative side coming out. This is a cute scene (as long as you''re no t the one on your knees). The pink background is a little too strong in my opinion. With a bit better lighting as well, your subjects would really stand out</td>', 'I see your creative side coming out. This is a cute scene (as long as you''re no t the one on your knees). The pink background is a little too strong in my opinion. With a bit better lighting as well, your subjects would really stand out', '2007-06-15 00:52:59.000000', NULL, 1),
(3786710, 532649, 31399, '<td valign="top">I love this, 9</td>', 'I love this, 9', '2007-06-15 00:53:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3786713, 534606, 31399, '<td valign="top">very beautiful, simply stunning lighting..gl 10</td>', 'very beautiful, simply stunning lighting..gl 10', '2007-06-15 00:53:34.000000', NULL, 1),
(3786715, 532987, 31399, '<td valign="top">very cool shot, even nice for "backside" challenge..lol..gl 9</td>', 'very cool shot, even nice for "backside" challenge..lol..gl 9', '2007-06-15 00:54:17.000000', NULL, 1),
(3786716, 530053, 35352, '<td valign="top">great work here - I really like the right hand side of the photo but would have loved more DOF to have more in focus. Unfortunately, this photo makes me think there''s something wrong with my eyes.</td>', 'great work here - I really like the right hand side of the photo but would have loved more DOF to have more in focus. Unfortunately, this photo makes me think there''s something wrong with my eyes.', '2007-06-15 00:54:26.000000', NULL, 1),
(3786717, 534126, 31399, '<td valign="top">one of my favorite in challenge...10</td>', 'one of my favorite in challenge...10', '2007-06-15 00:54:42.000000', NULL, 1),
(3786719, 531006, 31399, '<td valign="top">very very nice..love the contrasts... 10</td>', 'very very nice..love the contrasts... 10', '2007-06-15 00:55:01.000000', NULL, 1),
(3786722, 534768, 35352, '<td valign="top">Thats a head of hair! The lighting on his face is great and I like who the light on the window isn''t overpowering which is so easy to do. I also like the colour who''ve chosen for the duotone - very subtle but effective. His hand is a little too dark.</td>', 'Thats a head of hair! The lighting on his face is great and I like who the light on the window isn''t overpowering which is so easy to do. I also like the colour who''ve chosen for the duotone - very subtle but effective. His hand is a little too dark.', '2007-06-15 00:56:12.000000', NULL, 1),
(3786726, 533183, 35352, '<td valign="top">a nice silhouette, esp of the man. There''s a bit of noise up the top - maybe better to just crop it all out.</td>', 'a nice silhouette, esp of the man. There''s a bit of noise up the top - maybe better to just crop it all out.', '2007-06-15 00:57:22.000000', NULL, 1),
(3786728, 534768, 31399, '<td valign="top">Beautiful, very captivating and emotice. nice channels with the black and white..gl 10+</td>', 'Beautiful, very captivating and emotice. nice channels with the black and white..gl 10+', '2007-06-15 00:57:34.000000', NULL, 1),
(3786737, 534769, 35352, '<td valign="top">A nice capture of a butterfly. Shotting during the middle of the day brings out high contrast and I think there''s a bit too much in this photo. I like the orange in the butterfly - you could even saturate it a bit more.</td>', 'A nice capture of a butterfly. Shotting during the middle of the day brings out high contrast and I think there''s a bit too much in this photo. I like the orange in the butterfly - you could even saturate it a bit more.', '2007-06-15 00:58:59.000000', NULL, 1),
(3786741, 534860, 31399, '<td valign="top">beautiful..gl 8</td>', 'beautiful..gl 8', '2007-06-15 00:59:57.000000', NULL, 1),
(3786751, 532987, 79709, '<td valign="top">I love this picture.. I would have played with the color though.. seems a bit too orange. needs more real tones.. so that the sky looks more seperate from the ground..</td>', 'I love this picture.. I would have played with the color though.. seems a bit too orange. needs more real tones.. so that the sky looks more seperate from the ground..', '2007-06-15 01:02:12.000000', NULL, 1),
(3786754, 534846, 79709, '<td valign="top">WOW!! Amazing shot.. adding to favorites and 10</td>', 'WOW!! Amazing shot.. adding to favorites and 10', '2007-06-15 01:02:47.000000', NULL, 1),
(3786759, 534219, 31399, '<td valign="top">very very nice...think i''d like this wee more off-center..but still beautiful..gl 9+</td>', 'very very nice...think i''d like this wee more off-center..but still beautiful..gl 9+', '2007-06-15 01:03:46.000000', NULL, 1),
(3786766, 534545, 79709, '<td valign="top">I know who''s picture this is.. but I will vote fairly.. My feeling is the flower on bottom is distracting, her skin is too pink, and her right (my left) eye is not open.. would have been better as a candid shot honey.. reshoot.. you are a great photographer.. she''s a beautiful kid.. i''ll give you a 7 here.  :)</td>', 'I know who''s picture this is.. but I will vote fairly.. My feeling is the flower on bottom is distracting, her skin is too pink, and her right (my left) eye is not open.. would have been better as a candid shot honey.. reshoot.. you are a great photographer.. she''s a beautiful kid.. i''ll give you a 7 here.  :)', '2007-06-15 01:04:36.000000', NULL, 1),
(3786916, 533435, 73250, '<td valign="top">I love this shot...it''s title suits it. I just feel the emotion in it and it makes me happy.</td>', 'I love this shot...it''s title suits it. I just feel the emotion in it and it makes me happy.', '2007-06-15 01:49:42.000000', NULL, 1),
(3786990, 532604, 77724, '<td valign="top">How can this not put a smile on your face?  I feel the joy.</td>', 'How can this not put a smile on your face?  I feel the joy.', '2007-06-15 02:20:22.000000', NULL, 1),
(3786997, 534762, 77724, '<td valign="top">Nice capture, great color</td>', 'Nice capture, great color', '2007-06-15 02:27:27.000000', NULL, 1),
(3787003, 535225, 77724, '<td valign="top">Focus looks a little soft to me, reflection behind the cup and whatever that is in the upper right a little distracting.  Still, I like the idea and the wood tones are nice.</td>', 'Focus looks a little soft to me, reflection behind the cup and whatever that is in the upper right a little distracting.  Still, I like the idea and the wood tones are nice.', '2007-06-15 02:31:26.000000', NULL, 1),
(3787083, 534638, 64670, '<td valign="top">Lovely moment.</td>', 'Lovely moment.', '2007-06-15 03:26:16.000000', NULL, 1),
(3787086, 534425, 64670, '<td valign="top">The large expanse of white fur in the front it quite distracting, as it''s a much larger area than the face.  I think if the eyes were more in focus it would be better.</td>', 'The large expanse of white fur in the front it quite distracting, as it''s a much larger area than the face.  I think if the eyes were more in focus it would be better.', '2007-06-15 03:27:20.000000', NULL, 1),
(3787096, 533339, 64670, '<td valign="top">Fantastic clarity in this photo, but the subject matter lacks interest.</td>', 'Fantastic clarity in this photo, but the subject matter lacks interest.', '2007-06-15 03:31:19.000000', NULL, 1),
(3787109, 531006, 35352, '<td valign="top">Not a bad IR photo. I like the subject matter. Theres a few distracts though - the brickwork looks like noise and the grass still looks like grass even though its white. This may of worked better as a B+W.</td>', 'Not a bad IR photo. I like the subject matter. Theres a few distracts though - the brickwork looks like noise and the grass still looks like grass even though its white. This may of worked better as a B+W.', '2007-06-15 03:38:18.000000', NULL, 1),
(3787113, 532624, 35352, '<td valign="top">my favourite part of this photo is the nose of the plane - great colours of blue red and orange with that striking black of the propellers. The body of the plane could be even blacker to match. You could tilt this so that we can see the old crow writing better and show less of the grey wing. Great job!+</td>', 'my favourite part of this photo is the nose of the plane - great colours of blue red and orange with that striking black of the propellers. The body of the plane could be even blacker to match. You could tilt this so that we can see the old crow writing better and show less of the grey wing. Great job!+', '2007-06-15 03:44:43.000000', NULL, 1),
(3787124, 534428, 35352, '<td valign="top">this really works. Its simple yet has these contrasting areas. The only thing I can comment on is that its a bit busy in the bottom left corner unlike the rest of the photo. I like the grain in the sky - its reminds me of how photos use to look. (I''m no that old I hope)</td>', 'this really works. Its simple yet has these contrasting areas. The only thing I can comment on is that its a bit busy in the bottom left corner unlike the rest of the photo. I like the grain in the sky - its reminds me of how photos use to look. (I''m no that old I hope)', '2007-06-15 03:50:41.000000', NULL, 1),
(3787187, 535312, 35352, '<td valign="top">I like how you''ve divided up this photo - given the right amount of space to the sky and then shown the landscape below. This image appears a little grainy and the lady in red really stands out - she goes against your title.</td>', 'I like how you''ve divided up this photo - given the right amount of space to the sky and then shown the landscape below. This image appears a little grainy and the lady in red really stands out - she goes against your title.', '2007-06-15 04:43:00.000000', NULL, 1),
(3787192, 535547, 35352, '<td valign="top">very nice, I like how you have 3 distinct objects that are well defined, seem to have their own space in the photo and for 2 of them, are sharply in focus. I like the colours, esp the purpley blue of the top flower. I think this challenge calls for whites to really be white and it would have been better for you bottom flower not to have a colour cast to it. The yellow of that flower would have really stood out as well - though achieving that might of been hard in basic editing. A great photo!</td>', 'very nice, I like how you have 3 distinct objects that are well defined, seem to have their own space in the photo and for 2 of them, are sharply in focus. I like the colours, esp the purpley blue of the top flower. I think this challenge calls for whites to really be white and it would have been better for you bottom flower not to have a colour cast to it. The yellow of that flower would have really stood out as well - though achieving that might of been hard in basic editing. A great photo!', '2007-06-15 04:47:00.000000', NULL, 1),
(3787194, 531244, 28742, '<td valign="top">This pic has a serious case of ribbonitis! A solid ten.</td>', 'This pic has a serious case of ribbonitis! A solid ten.', '2007-06-15 04:47:27.000000', NULL, 1),
(3787198, 532429, 28742, '<td valign="top">Go ahead, shoot yourself! ;-P Love the lighting and the bw processing - very well done. Good luck!</td>', 'Go ahead, shoot yourself! ;-P Love the lighting and the bw processing - very well done. Good luck!', '2007-06-15 04:50:27.000000', NULL, 1),
(3787199, 533399, 28742, '<td valign="top">BW doesn''t work for me for this scene, I''m afraid. Would love to see the color version.</td>', 'BW doesn''t work for me for this scene, I''m afraid. Would love to see the color version.', '2007-06-15 04:51:14.000000', NULL, 1),
(3787204, 535569, 28742, '<td valign="top">My comment is "huh?" but with all caps. I would''ve given it a 10 but a spelling error took nine of those points away. ...just kidding.</td>', 'My comment is "huh?" but with all caps. I would''ve given it a 10 but a spelling error took nine of those points away. ...just kidding.', '2007-06-15 04:53:41.000000', NULL, 1),
(3787206, 535540, 28742, '<td valign="top">copy, print, frame, hang on wall. Hope you don''t mind. ;-) Just awesome.</td>', 'copy, print, frame, hang on wall. Hope you don''t mind. ;-) Just awesome.', '2007-06-15 04:55:40.000000', NULL, 1),
(3787210, 534541, 28742, '<td valign="top">Dare I say DNMC? Well, I just don''t get the connection. It is a great image though - spooky and nostalgic. Good luck.</td>', 'Dare I say DNMC? Well, I just don''t get the connection. It is a great image though - spooky and nostalgic. Good luck.', '2007-06-15 04:58:00.000000', NULL, 1),
(3787216, 530613, 28742, '<td valign="top">Were it not for the focus issue, this would be in my faves. Please don''t tell me you softened it in post proc - the result only hurts an otherwise beautiful image. If you like it however, that''s all that really matters. ...except in regards to the challenge placement of course. :) For the record, I am giving it a 7 - it deserves that.</td>', 'Were it not for the focus issue, this would be in my faves. Please don''t tell me you softened it in post proc - the result only hurts an otherwise beautiful image. If you like it however, that''s all that really matters. ...except in regards to the challenge placement of course. :) For the record, I am giving it a 7 - it deserves that.', '2007-06-15 05:16:42.000000', NULL, 1),
(3787221, 534427, 28742, '<td valign="top">LOL - took me awhile to figure out whose hands were whose - sorry, it''s late and I''m groogy. :) Except for the bright spot or reflection on the woman''s side, this is an excellent "we''re having a baby" type images. Good luck to you and to the soon to be new parents. :)</td>', 'LOL - took me awhile to figure out whose hands were whose - sorry, it''s late and I''m groogy. :) Except for the bright spot or reflection on the woman''s side, this is an excellent "we''re having a baby" type images. Good luck to you and to the soon to be new parents. :)', '2007-06-15 05:20:21.000000', NULL, 1),
(3787223, 534269, 28742, '<td valign="top">even lighting on the face would have gained 2 points from me. You''ll have to settle for a 6. :)Good luck though.</td>', 'even lighting on the face would have gained 2 points from me. You''ll have to settle for a 6. :)Good luck though.', '2007-06-15 05:21:29.000000', NULL, 1),
(3787225, 535581, 28742, '<td valign="top">Beauteous! Lovely and perfect.</td>', 'Beauteous! Lovely and perfect.', '2007-06-15 05:22:25.000000', NULL, 1),
(3787226, 532392, 28742, '<td valign="top">For crying out loud, who has plastic steers on their ranch?? Don''t they know how tough the meat is?? :P</td>', 'For crying out loud, who has plastic steers on their ranch?? Don''t they know how tough the meat is?? :P', '2007-06-15 05:24:23.000000', NULL, 1),
(3787227, 530416, 28742, '<td valign="top">Yeah, pure white except for the blue....ribbon, that is. :) At least a top ten - outstanding.</td>', 'Yeah, pure white except for the blue....ribbon, that is. :) At least a top ten - outstanding.', '2007-06-15 05:25:54.000000', NULL, 1),
(3787231, 534305, 28742, '<td valign="top">Awesome! I''m totally into that as well. I could stit there and just make that thing spin all day. ;-) Just yankin. Love the guy''s grin. Nice BW conversion here as well. Best of luck!</td>', 'Awesome! I''m totally into that as well. I could stit there and just make that thing spin all day. ;-) Just yankin. Love the guy''s grin. Nice BW conversion here as well. Best of luck!', '2007-06-15 05:27:51.000000', NULL, 1),
(3787234, 534846, 28742, '<td valign="top">This reminds me of a Neil Shapiro, but I suspect it is not. Take it as a compliment though - this is a fantastic image. Love the color!</td>', 'This reminds me of a Neil Shapiro, but I suspect it is not. Take it as a compliment though - this is a fantastic image. Love the color!', '2007-06-15 05:29:53.000000', NULL, 1),
(3787237, 531753, 28742, '<td valign="top">Uh... yeah, until he sees the punji sticks! ;-)</td>', 'Uh... yeah, until he sees the punji sticks! ;-)', '2007-06-15 05:31:24.000000', NULL, 1),
(3787240, 535228, 28742, '<td valign="top">''Twould be much better if the woman''s eyes were looking at the baby - she seems disconnected. Beautiful child though. Best of luck.</td>', '''Twould be much better if the woman''s eyes were looking at the baby - she seems disconnected. Beautiful child though. Best of luck.', '2007-06-15 05:34:50.000000', NULL, 1),
(3787246, 534521, 28742, '<td valign="top">LOL - I''m envisioning thought bubbles with all sorts of Valley-Girl-esque thoughts. ;-) j/k - they''re all very lovely girls and probably very smart as well. ...except for the blondes. :P Sorry can''t help myself. Great image though - well executed and a fun image overall. Good luck.</td>', 'LOL - I''m envisioning thought bubbles with all sorts of Valley-Girl-esque thoughts. ;-) j/k - they''re all very lovely girls and probably very smart as well. ...except for the blondes. :P Sorry can''t help myself. Great image though - well executed and a fun image overall. Good luck.', '2007-06-15 05:40:09.000000', NULL, 1),
(3787248, 533604, 28742, '<td valign="top">Looks like even the neighbors will get fed tonight! Heehee. Great image, cute girl with a great smile. Pure Joy indeed.</td>', 'Looks like even the neighbors will get fed tonight! Heehee. Great image, cute girl with a great smile. Pure Joy indeed.', '2007-06-15 05:41:19.000000', NULL, 1),
(3787249, 534629, 28742, '<td valign="top">Is that a dead cat I see in the background? LOL - just funnin. :)</td>', 'Is that a dead cat I see in the background? LOL - just funnin. :)', '2007-06-15 05:42:04.000000', NULL, 1),
(3787255, 534390, 28742, '<td valign="top">What an angel! Those eyes are mesmerizing and I love the slight hint of a smile - purely content.</td>', 'What an angel! Those eyes are mesmerizing and I love the slight hint of a smile - purely content.', '2007-06-15 05:44:28.000000', NULL, 1),
(3787262, 535485, 22011, '<td valign="top">Yikes, all the water is going to run out the side....! :-).  This is a nice study, but in this case I really don''t think the tilted horizon works.</td>', 'Yikes, all the water is going to run out the side....! :-).  This is a nice study, but in this case I really don''t think the tilted horizon works.', '2007-06-15 05:54:58.000000', NULL, 1),
(3787283, 534706, 30982, '<td valign="top">How sweet!  For your purposes (or the parents''), there''s a bit of a tungsten light color cast (yellow) to this that can be removed in post processing.  Ask in the forums if you''re not sure what I''m suggesting.</td>', 'How sweet!  For your purposes (or the parents''), there''s a bit of a tungsten light color cast (yellow) to this that can be removed in post processing.  Ask in the forums if you''re not sure what I''m suggesting.', '2007-06-15 06:11:22.000000', NULL, 1),
(3787286, 535261, 30982, '<td valign="top">Those eyes are wonderful!!  You may want to try a crop that removes most of the feet at the top - that will put the baby''s eyes on more of a thirds line focal point than at the halfway point, which balances a bit better.</td>', 'Those eyes are wonderful!!  You may want to try a crop that removes most of the feet at the top - that will put the baby''s eyes on more of a thirds line focal point than at the halfway point, which balances a bit better.', '2007-06-15 06:13:18.000000', NULL, 1),
(3787287, 532490, 30982, '<td valign="top">I''m trying to guess titles before I read them - I''d have titled this one Pure Chaos.  Neat shot, interesting textures and I like its chaotic nature.</td>', 'I''m trying to guess titles before I read them - I''d have titled this one Pure Chaos.  Neat shot, interesting textures and I like its chaotic nature.', '2007-06-15 06:14:09.000000', NULL, 1),
(3787289, 530416, 30982, '<td valign="top">Cool - an albino peacock?</td>', 'Cool - an albino peacock?', '2007-06-15 06:15:06.000000', NULL, 1),
(3787290, 534174, 30982, '<td valign="top">Great light, wonderfully compelling eyes.  An excellent portrait.</td>', 'Great light, wonderfully compelling eyes.  An excellent portrait.', '2007-06-15 06:15:36.000000', NULL, 1),
(3787303, 532468, 30982, '<td valign="top">Well shot and well processed - the reds are a nice touch in this, particularly the construction tape to the left.  Warm tones, very rich - quite well suited to the subject.</td>', 'Well shot and well processed - the reds are a nice touch in this, particularly the construction tape to the left.  Warm tones, very rich - quite well suited to the subject.', '2007-06-15 06:31:20.000000', NULL, 1),
(3787305, 534518, 30982, '<td valign="top">How very lovely!  I love the way the dresses flow along the stage.</td>', 'How very lovely!  I love the way the dresses flow along the stage.', '2007-06-15 06:32:34.000000', NULL, 1),
(3787306, 533937, 30982, '<td valign="top">Indeed!  And a very nice shot all its own, too.</td>', 'Indeed!  And a very nice shot all its own, too.', '2007-06-15 06:36:04.000000', NULL, 1),
(3787307, 534813, 30982, '<td valign="top">Very sweet!</td>', 'Very sweet!', '2007-06-15 06:36:16.000000', NULL, 1),
(3787309, 533399, 30982, '<td valign="top">Very visually pleasing to me - I love the mist line as it travels through.</td>', 'Very visually pleasing to me - I love the mist line as it travels through.', '2007-06-15 06:37:49.000000', NULL, 1),
(3787312, 534365, 30982, '<td valign="top">I know they don''t really smile, but it sure does look like an innocent, shy kinda smile to me.  Nice choice for the challenge!</td>', 'I know they don''t really smile, but it sure does look like an innocent, shy kinda smile to me.  Nice choice for the challenge!', '2007-06-15 06:39:07.000000', NULL, 1),
(3787313, 533681, 30982, '<td valign="top">LOL!  Made me smile.  They are so incredibly ugle when they''re this size!</td>', 'LOL!  Made me smile.  They are so incredibly ugle when they''re this size!', '2007-06-15 06:39:32.000000', NULL, 1),
(3787316, 535538, 30982, '<td valign="top">This could be a bit bigger - there''s a good tutorial under the "Learn" button on the toolbar that will help you resize your photographs for maximum impact here at DPC.  Your subject (the fruit) seems to be out of focus.  Does look like a nice setting for a picnic!</td>', 'This could be a bit bigger - there''s a good tutorial under the "Learn" button on the toolbar that will help you resize your photographs for maximum impact here at DPC.  Your subject (the fruit) seems to be out of focus.  Does look like a nice setting for a picnic!', '2007-06-15 06:42:14.000000', NULL, 1),
(3787317, 535346, 30982, '<td valign="top">Love the enthusiasm!  And I like that the way the arms are, looks like he (she?) almost took this as a self-portrait, which gives it even more of a kick.  Fun!</td>', 'Love the enthusiasm!  And I like that the way the arms are, looks like he (she?) almost took this as a self-portrait, which gives it even more of a kick.  Fun!', '2007-06-15 06:42:54.000000', NULL, 1),
(3787318, 534754, 30982, '<td valign="top">I can very much relate to this one.</td>', 'I can very much relate to this one.', '2007-06-15 06:43:51.000000', NULL, 1),
(3787331, 534575, 68426, '<td valign="top">Delightful - a real joy :)</td>', 'Delightful - a real joy :)', '2007-06-15 07:10:49.000000', NULL, 1),
(3787364, 533023, 47906, '<td valign="top">This is cute, I like how the sugar looks like its formed into little hearts.</td>', 'This is cute, I like how the sugar looks like its formed into little hearts.', '2007-06-15 07:41:48.000000', NULL, 1),
(3787365, 533413, 47906, '<td valign="top">Beautiful crisp colors. nice shot.</td>', 'Beautiful crisp colors. nice shot.', '2007-06-15 07:42:12.000000', NULL, 1),
